let _pass = 0;
let _fail = 0;
function _test(num: number, got: any, expected: any) {
    const passed = got === expected;
    console.log('---------------------');
    console.log('Test ' + num + ':');
    console.log('Output: ' + got);
    console.log(passed ? 'Pass' : 'Fail');
    if (passed) _pass++; else _fail++;
}
const earth = new Planet('Earth', 6371);
const sun = new Star('Sun', 5778);
_test(1, earth.describe(), 'Earth has radius 6371 km');
_test(2, sun.describe(), 'Sun burns at 5778K');
const mars = new Planet('Mars', 3389);
_test(3, mars.describe(), 'Mars has radius 3389 km');
const sirius = new Star('Sirius', 9940);
_test(4, sirius.describe(), 'Sirius burns at 9940K');
console.log('---------------------');
console.log(_pass + ' passed, ' + _fail + ' failed');

